pub fn node_type_deps(n: Rc<Node>) -> Rc<Vec<String>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        {
            let n_is_type_var = if (n.inferred.clone() != None) {
                is_type_variable(n.inferred.clone().clone().unwrap())
} else {
                false
};
if n_is_type_var {
                return Rc::new(vec![])
}
let __is_named_ref = if (n.inferred.clone() == None) {
                false
} else {
                match (*rt_node(n.clone())).clone() {
    NodeType::Typed { node: rt, .. } => (((((rt.connective.clone() == Connective::NoConnective) && ((rt.children.clone().len() as i64) == 0)) && (rt.name.clone().as_str() != "".to_string().as_str())) && (rt.name.clone().as_str() != "None".to_string().as_str())) && (is_kernel_type(rt.name.clone()) == false)),
    NodeType::InferError { .. } => false,
    NodeType::InferVariable { .. } => false,
    NodeType::Untyped => false,
}
};
let has_structure = (n.connective.clone() != Connective::NoConnective);
if __is_named_ref {
                match (*rt_node(n.clone())).clone() {
    NodeType::Typed { node: rt, .. } => Rc::new(vec![rt.name.clone()]),
    NodeType::InferError { .. } => Rc::new(vec![]),
    NodeType::InferVariable { .. } => Rc::new(vec![]),
    NodeType::Untyped => Rc::new(vec![]),
}
} else {
                if has_structure {
                    Rc::new({ let mut __result = Vec::new(); for child in n.children.clone().iter().cloned() { __result.extend((*if (child.inferred.clone() != None) {
                        match (*rt_node(child.clone())).clone() {
    NodeType::Typed { node: rt, .. } => node_type_deps(rt.clone()),
    NodeType::InferError { .. } => Rc::new(vec![]),
    NodeType::InferVariable { .. } => Rc::new(vec![]),
    NodeType::Untyped => Rc::new(vec![]),
}
} else {
                        node_type_deps(child.clone())
}).iter().cloned()); } __result })
} else {
                    if (n.inferred.clone() != None) {
                        match (*rt_node(n.clone())).clone() {
    NodeType::Typed { node: rt, .. } => node_type_deps(rt.clone()),
    NodeType::InferError { .. } => Rc::new(vec![]),
    NodeType::InferVariable { .. } => Rc::new(vec![]),
    NodeType::Untyped => Rc::new(vec![]),
}
} else {
                        if ((n.children.clone().len() as i64) > 0) {
                            {
                                let child_deps = Rc::new({ let mut __result = Vec::new(); for child in n.children.clone().iter().cloned() { __result.extend((*node_type_deps(child.clone())).iter().cloned()); } __result });
if ((n.name.clone().as_str() != "".to_string().as_str()) && (is_kernel_type(n.name.clone()) == false)) {
                                    v2_rt::concat(Rc::new(vec![n.name.clone()]), child_deps)
} else {
                                    child_deps
}
}
} else {
                            if ((is_kernel_type(n.name.clone()) || (n.name.clone().as_str() == none_type().name.clone().as_str())) || (n.name.clone().as_str() == "".to_string().as_str())) {
                                Rc::new(vec![])
} else {
                                Rc::new(vec![n.name.clone()])
}
}
}
}
}
}
    })
}

pub fn infer_literal_node(lit: Rc<LiteralValue>) -> Rc<Node> {
    match (*lit).clone() {
    LiteralValue::LitStr { .. } => string_type(),
    LiteralValue::LitInt { .. } => int_type(),
    LiteralValue::LitFloat { .. } => float_type(),
    LiteralValue::LitBool { .. } => bool_type(),
    LiteralValue::LitNull => with_optional_cardinality(unit_type()),
}
}

pub fn method_receiver_element_node(receiver_type: Rc<Node>) -> Rc<Node> {
    {
        let normed = normalize_access_type_node(receiver_type.clone());
let maybe_element = if node_is_keyed_collection(normed.clone()) {
            normed.children.clone().get(1 as usize).cloned()
} else {
            if ((normed.connective.clone() == Connective::NoConnective) && ((normed.children.clone().len() as i64) == 1)) {
                normed.children.clone().first().cloned()
} else {
                None
}
};
match maybe_element {
    Some(el) => el.clone(),
    None => receiver_type.clone(),
}
}
}

pub fn extract_optional_inner_node(n: Rc<Node>) -> Rc<Node> {
    {
        let is_optional = (n.return_cardinality.clone() == Cardinality::CardOptional);
if is_optional {
            with_required_cardinality(n.clone())
} else {
            n.clone()
}
}
}

pub fn binop_algebra_field(op: BinOp) -> String {
    match op {
    BinOp::Add => "add".to_string(),
    BinOp::Sub => "add".to_string(),
    BinOp::Mul => "mul".to_string(),
    BinOp::Div => "reciprocal".to_string(),
    BinOp::Mod => "add".to_string(),
    BinOp::Eq => "compare".to_string(),
    BinOp::Ne => "compare".to_string(),
    BinOp::Lt => "compare".to_string(),
    BinOp::Gt => "compare".to_string(),
    BinOp::Le => "compare".to_string(),
    BinOp::Ge => "compare".to_string(),
    BinOp::And => "meet".to_string(),
    BinOp::Or => "join".to_string(),
    BinOp::NullCoalesce => "".to_string(),
}
}

pub fn infer_binop_type_node(op: BinOp, left_type: Rc<Node>) -> Rc<Node> {
    match op.clone() {
    BinOp::Eq => bool_type(),
    BinOp::Ne => bool_type(),
    BinOp::Lt => bool_type(),
    BinOp::Gt => bool_type(),
    BinOp::Le => bool_type(),
    BinOp::Ge => bool_type(),
    BinOp::And => bool_type(),
    BinOp::Or => bool_type(),
    BinOp::NullCoalesce => extract_optional_inner_node(left_type.clone()),
    _ => {
        let field_name = binop_algebra_field(op.clone());
let is_product = (left_type.connective.clone() == Connective::Conj);
if is_product {
            {
                let matching = Rc::new({ let mut __result = Vec::new(); for c in left_type.children.clone().iter().cloned() { if (c.name.clone().as_str() == field_name.clone().as_str()) { __result.push(c); } } __result });
match matching.first().cloned() {
    Some(field) => match field.inferred.clone().as_deref().cloned() {
    Some(InferredNode::Resolved { node: rt, .. }) => if ((rt.params.clone().len() as i64) > 0) {
                    match rt.inferred.clone().as_deref().cloned() {
    Some(InferredNode::Resolved { node: return_type, .. }) => return_type.clone(),
    _ => left_type.clone(),
}
} else {
                    rt.clone()
},
    _ => left_type.clone(),
},
    None => left_type.clone(),
}
}
} else {
            left_type.clone()
}
},
}
}

pub fn for_each_element_type_node(n: Rc<Node>) -> Rc<Node> {
    {
        let normed = normalize_access_type_node(n);
let is_single_child = ((normed.connective.clone() == Connective::NoConnective) && ((normed.children.clone().len() as i64) == 1));
let extracted = if is_single_child {
            normed.children.clone().first().cloned()
} else {
            None
};
match extracted {
    Some(el) => el.clone(),
    None => if ((((normed.connective.clone() == Connective::NoConnective) && ((normed.children.clone().len() as i64) == 0)) && ((normed.properties.clone().len() as i64) == 0)) && (normed.name.clone().as_str() == string_type().name.clone().as_str())) {
            string_type()
} else {
            normed.clone()
},
}
}
}

